# Get the script's directory
$scriptPath = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $scriptPath

Write-Host "Starting backend server in $scriptPath"

# Create logs directory if it doesn't exist
if (-not (Test-Path "logs")) {
    New-Item -ItemType Directory -Path "logs"
    Write-Host "Created logs directory"
}

# Install dependencies
Write-Host "Installing backend dependencies..."
npm install

# Check if installation was successful
if ($LASTEXITCODE -eq 0) {
    Write-Host "Backend dependencies installed successfully."
    
    # Build TypeScript files
    Write-Host "Building TypeScript files..."
    npm run backend:build
    
    if ($LASTEXITCODE -eq 0) {
        Write-Host "TypeScript build successful."
        Write-Host "Starting backend server..."
        Write-Host "Server will be available at http://localhost:3000"
        
        # Start the server using the new script
        npm run backend:dev
    } else {
        Write-Host "Failed to build TypeScript files. Please check the error messages above."
        exit 1
    }
} else {
    Write-Host "Failed to install backend dependencies. Please check the error messages above."
    exit 1
} 